package alphametics

import (
	"errors"
	"sort"
	"strings"
)

// Solve solves an alphametics puzzle.
//
// The puzzle is a string of the form "WORD + WORD + ... == WORD", where the
// left hand side is one or more words joined by " + " and the right hand side
// is a single word. Each distinct letter must map to a distinct digit, and the
// leading letter of any multi-digit word must not map to zero.
//
// Solve returns a map from each letter to its digit, or an error if the puzzle
// has no valid solution.
func Solve(puzzle string) (map[string]int, error) {
	addends, result, ok := parse(puzzle)
	if !ok {
		return nil, errors.New("invalid puzzle")
	}

	// Build the linear equation sum(addends) == result as
	//   sum over letters of coeff[letter] * digit[letter] == 0
	// where coeff accumulates +10^pos for each occurrence in an addend and
	// -10^pos for each occurrence in the result.
	maxLen := 0
	for _, w := range addends {
		if len(w) > maxLen {
			maxLen = len(w)
		}
	}
	if len(result) > maxLen {
		maxLen = len(result)
	}
	pow10 := make([]int64, maxLen+1)
	pow10[0] = 1
	for i := 1; i <= maxLen; i++ {
		pow10[i] = pow10[i-1] * 10
	}

	coeff := make(map[rune]int64)
	leading := make(map[rune]bool)
	for _, w := range addends {
		accumulate(w, 1, pow10, coeff, leading)
	}
	accumulate(result, -1, pow10, coeff, leading)

	// Order letters so that the most significant (largest |coefficient|) are
	// assigned first; this makes the pruning bound kick in earlier.
	letters := make([]rune, 0, len(coeff))
	for r := range coeff {
		letters = append(letters, r)
	}
	sort.Slice(letters, func(i, j int) bool {
		return abs64(coeff[letters[i]]) > abs64(coeff[letters[j]])
	})

	n := len(letters)
	if n > 10 {
		// More than ten distinct letters cannot map to ten distinct digits.
		return nil, errors.New("no solution")
	}

	// Precompute suffix bounds for pruning. For the letters from idx onward,
	// suffixMin[idx] is the least they could contribute and suffixMax[idx] the
	// greatest (each digit is bounded to [0,9]); the true range is narrower,
	// so these are safe, conservative bounds.
	suffixMin := make([]int64, n+1)
	suffixMax := make([]int64, n+1)
	for i := n - 1; i >= 0; i-- {
		suffixMin[i] = suffixMin[i+1]
		suffixMax[i] = suffixMax[i+1]
		c := coeff[letters[i]]
		if c >= 0 {
			suffixMax[i] += c * 9
		} else {
			suffixMin[i] += c * 9
		}
	}

	assignment := make([]int, n)
	for i := range assignment {
		assignment[i] = -1
	}
	used := make([]bool, 10)

	var dfs func(idx int, sum int64) bool
	dfs = func(idx int, sum int64) bool {
		if idx == n {
			return sum == 0
		}
		// Prune: 0 must lie within the reachable range of the final sum.
		if sum+suffixMin[idx] > 0 || sum+suffixMax[idx] < 0 {
			return false
		}
		start := 0
		if leading[letters[idx]] {
			start = 1 // leading digit may not be zero
		}
		for d := start; d <= 9; d++ {
			if used[d] {
				continue
			}
			used[d] = true
			assignment[idx] = d
			if dfs(idx+1, sum+coeff[letters[idx]]*int64(d)) {
				return true
			}
			used[d] = false
		}
		assignment[idx] = -1
		return false
	}

	if !dfs(0, 0) {
		return nil, errors.New("no solution")
	}

	res := make(map[string]int, n)
	for i, r := range letters {
		res[string(r)] = assignment[i]
	}
	return res, nil
}

// parse splits a puzzle into its addends (left of "==") and result (right of
// "=="). It reports ok=false if the puzzle is malformed.
func parse(puzzle string) (addends []string, result string, ok bool) {
	parts := strings.Split(puzzle, "==")
	if len(parts) != 2 {
		return nil, "", false
	}
	for _, a := range strings.Split(parts[0], "+") {
		a = strings.TrimSpace(a)
		if a != "" {
			addends = append(addends, a)
		}
	}
	result = strings.TrimSpace(parts[1])
	if len(addends) == 0 || result == "" {
		return nil, "", false
	}
	return addends, result, true
}

// accumulate adds sign*10^pos to the coefficient of each letter in word and
// records word's first letter as a leading letter when the word is multi-digit.
func accumulate(word string, sign int64, pow10 []int64, coeff map[rune]int64, leading map[rune]bool) {
	if len(word) > 1 {
		leading[rune(word[0])] = true
	}
	n := len(word)
	for i := 0; i < n; i++ {
		coeff[rune(word[i])] += sign * pow10[n-1-i]
	}
}

func abs64(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

